// SettingsServiceClient is a client for the nagi.v1.SettingsService service.
type SettingsServiceClient interface {
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	// 绑定面板域名（为空表示取消），自动申请正式证书。节点的控制连接和安装命令仍然用 IP:端口 + 公钥指纹。
	SetPanelDomain(context.Context, *connect.Request[v1.SetPanelDomainApiRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	GetAlertConfig(context.Context, *connect.Request[v1.GetAlertConfigRequest]) (*connect.Response[v1.GetAlertConfigResponse], error)
	UpdateAlertConfig(context.Context, *connect.Request[v1.UpdateAlertConfigRequest]) (*connect.Response[v1.UpdateAlertConfigResponse], error)
	// 用面板发一条测试消息到某个渠道。
	TestAlertChannel(context.Context, *connect.Request[v1.TestAlertChannelRequest]) (*connect.Response[v1.TestAlertChannelResponse], error)
	// 生成接入码：其他面板用它把节点交给本面板。1 小时内可以给多个节点用。
	CreateInvite(context.Context, *connect.Request[v1.CreateInviteRequest]) (*connect.Response[v1.CreateInviteResponse], error)
	// 还在有效期内的接入码。
	ListInvites(context.Context, *connect.Request[v1.ListInvitesRequest]) (*connect.Response[v1.ListInvitesResponse], error)
	// 提前作废接入码。
	RevokeInvite(context.Context, *connect.Request[v1.RevokeInviteRequest]) (*connect.Response[v1.RevokeInviteResponse], error)
	// 主备面板（见 docs/standby.md）：生成配对码、列出和移除备用面板；备用面板上返回自己的同步状态。
	CreateStandbyCode(context.Context, *connect.Request[v1.CreateStandbyCodeRequest]) (*connect.Response[v1.CreateStandbyCodeResponse], error)
	GetStandbys(context.Context, *connect.Request[v1.GetStandbysRequest]) (*connect.Response[v1.GetStandbysResponse], error)
	RemoveStandby(context.Context, *connect.Request[v1.RemoveStandbyRequest]) (*connect.Response[v1.RemoveStandbyResponse], error)
	// 账号安全：两步验证和安全入口。
	GetSecurity(context.Context, *connect.Request[v1.GetSecurityRequest]) (*connect.Response[v1.Security], error)
	// 开始设置两步验证：返回密钥和验证器 App 扫码用的地址，10 分钟内用 EnableTOTP 确认。
	BeginTOTP(context.Context, *connect.Request[v1.BeginTOTPRequest]) (*connect.Response[v1.BeginTOTPResponse], error)
	EnableTOTP(context.Context, *connect.Request[v1.EnableTOTPRequest]) (*connect.Response[v1.Security], error)
	// 关闭两步验证，需要当前的验证码或者密码。
	DisableTOTP(context.Context, *connect.Request[v1.DisableTOTPRequest]) (*connect.Response[v1.Security], error)
	// 开启（生成新的随机路径）或关闭安全入口。
	SetEntrance(context.Context, *connect.Request[v1.SetEntranceRequest]) (*connect.Response[v1.Security], error)
}

